import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# ------------------------------------------------------------------
# CUDA kernel: simple tiled batched GEMM (fp16 inputs, fp32 accumulation,
# fp16 output).  Tile size 16x16 so each thread produces one output element.
# ------------------------------------------------------------------
cuda_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cuda_fp16.h>

#ifndef BLOCK_SIZE
#define BLOCK_SIZE 16          // tile dimension (must divide 16 for good occupancy)
#endif

// ------------------------------------------------------------------
// Kernel
// ------------------------------------------------------------------
__global__ void batched_gemm_kernel(
    const __half* __restrict__ A,
    const __half* __restrict__ B,
    __half* __restrict__ C,
    int batch,
    int M,
    int N,
    int K)
{
    // ----- block / thread coordinates -----
    const int batch_idx = blockIdx.z;
    if (batch_idx >= batch) return;

    const int row = blockIdx.y * BLOCK_SIZE + threadIdx.y;   // output row
    const int col = blockIdx.x * BLOCK_SIZE + threadIdx.x;   // output col

    const size_t a_batch_offset = static_cast<size_t>(batch_idx) * M * K;
    const size_t b_batch_offset = static_cast<size_t>(batch_idx) * K * N;
    const size_t c_batch_offset = static_cast<size_t>(batch_idx) * M * N;

    // ----- accumulation in fp32 -----
    float acc = 0.0f;

    // ----- shared memory tiles -----
    __shared__ __half As[BLOCK_SIZE][BLOCK_SIZE];
    __shared__ __half Bs[BLOCK_SIZE][BLOCK_SIZE];

    // ----- loop over K dimension in tiles -----
    for (int t = 0; t < K; t += BLOCK_SIZE) {
        // load A tile (row-major)
        int a_row = row;
        int a_col = t + threadIdx.x;
        if (a_row < M && a_col < K) {
            As[threadIdx.y][threadIdx.x] = A[a_batch_offset + static_cast<size_t>(a_row) * K + a_col];
        } else {
            As[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        // load B tile (row-major in memory, but we treat it as column for multiplication)
        int b_row = t + threadIdx.y;
        int b_col = col;
        if (b_row < K && b_col < N) {
            Bs[threadIdx.y][threadIdx.x] = B[b_batch_offset + static_cast<size_t>(b_row) * N + b_col];
        } else {
            Bs[threadIdx.y][threadIdx.x] = __float2half(0.0f);
        }

        __syncthreads();

        // compute partial products
        #pragma unroll
        for (int k = 0; k < BLOCK_SIZE; ++k) {
            acc += __half2float(As[threadIdx.y][k]) * __half2float(Bs[k][threadIdx.x]);
        }

        __syncthreads();
    }

    // ----- write result -----
    if (row < M && col < N) {
        C[c_batch_offset + static_cast<size_t>(row) * N + col] = __float2half(acc);
    }
}

// ------------------------------------------------------------------
// C++ wrapper
// ------------------------------------------------------------------
torch::Tensor batched_gemm_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda() && B.is_cuda(),
                "inputs must be CUDA tensors");
    TORCH_CHECK(A.dtype() == torch::kFloat16 && B.dtype() == torch::kFloat16,
                "inputs must be float16 (half)");
    TORCH_CHECK(A.dim() == 3 && B.dim() == 3,
                "inputs must be 3‑D tensors (batch, M, K) and (batch, K, N)");

    const int batch = A.size(0);
    const int M = A.size(1);
    const int K = A.size(2);
    TORCH_CHECK(B.size(0) == batch && B.size(1) == K,
                "B must have shape (batch, K, N)");
    const int N = B.size(2);

    auto C = torch::empty({batch, M, N},
                          torch::TensorOptions()
                              .dtype(torch::kFloat16)
                              .device(A.device()));

    // launch configuration: one block per 16x16 output tile
    dim3 block(BLOCK_SIZE, BLOCK_SIZE);
    dim3 grid((N + BLOCK_SIZE - 1) / BLOCK_SIZE,
              (M + BLOCK_SIZE - 1) / BLOCK_SIZE,
              batch);

    batched_gemm_kernel<<<grid, block>>>(
        reinterpret_cast<const __half*>(A.data_ptr()),
        reinterpret_cast<const __half*>(B.data_ptr()),
        reinterpret_cast<__half*>(C.data_ptr()),
        batch, M, N, K);

    // check for launch errors
    cudaError_t err = cudaGetLastError();
    if (err != cudaSuccess) {
        AT_ERROR("CUDA error in batched_gemm_kernel: ", cudaGetErrorString(err));
    }

    return C;
}
'''

