'''

# ------------------------------------------------------------------
# Compile the extension
# ------------------------------------------------------------------
ext = load_inline(
    name="batched_gemm_ext",
    cpp_sources=cpp_header,
    cuda_sources=cuda_source,
    functions=["batched_gemm_cuda"],
    verbose=False,
)

# ------------------------------------------------------------------
# PyTorch module exposing the custom operator
# ------------------------------------------------------------------
class ModelNew(nn.Module):
    """
    Batched matrix multiplication (fp16) using a tiled CUDA kernel.
    """
    def __init__(self):
        super().__init__()
        self._gemm = ext

    def forward(self, A: torch.Tensor, B: torch.Tensor) -> torch.Tensor:
        # ensure inputs are on CUDA and half precision
        if not A.is_cuda:
            A = A.cuda()
        if not B.is_cuda:
            B = B.cuda()
        if A.dtype != torch.float16:
            A = A.half()
        if B.dtype != torch.float16:
            B = B.half()
        return self._gemm.batched_gemm_cuda(A, B)
